/**
 * Represents the arguments for the `dragStart`, `dragOver`, and `dragEnd` events.
 * @hidden
 */
export interface SortableEvent {
    /**
     * Specifies the index of the data item.
     */
    index: number;
    /**
     * Specifies the previous index of the data item.
     */
    oldIndex: number;
}
